// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — the face is decided by bounceOffBricks() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision resolution (issue #1) ---------------------------------

// Continuous (swept) collision: the move from (px, py) to the ball's current
// position is a segment; we test it against the brick grown by the ball radius
// (the expanded AABB). Returns the entry time t in [0, 1] along that segment,
// or null if the segment never touches the brick. t = 0 means the ball already
// overlapped the brick at the start of the move.
//
// This is what defeats tunnelling: at `ballSpeed(6)` (710 px/s) a stuttered
// frame (50 ms cap) moves the ball 35.5 px, more than the 34 px needed to
// clear a brick (BRICK_H + diameter) — a discrete before/after test would
// never see the overlap, the sweep does.
function sweepHit(ball, px, py, brick) {
  const ex = brick.x - ball.r;
  const ey = brick.y - ball.r;
  const ew = brick.w + 2 * ball.r;
  const eh = brick.h + 2 * ball.r;
  const dx = ball.x - px;
  const dy = ball.y - py;

  let tEntry = 0;
  let tExit = 1;

  // Slab test on x.
  if (Math.abs(dx) < 1e-12) {
    if (px <= ex || px >= ex + ew) return null;
  } else {
    let t1 = (ex - px) / dx;
    let t2 = (ex + ew - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEntry = Math.max(tEntry, t1);
    tExit = Math.min(tExit, t2);
  }
  // Slab test on y.
  if (Math.abs(dy) < 1e-12) {
    if (py <= ey || py >= ey + eh) return null;
  } else {
    let t1 = (ey - py) / dy;
    let t2 = (ey + eh - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEntry = Math.max(tEntry, t1);
    tExit = Math.min(tExit, t2);
  }

  if (tEntry <= tExit && tEntry <= 1 && tExit >= 0) return Math.max(0, tEntry);
  return null;
}

// Bounces the ball off the face with the smallest penetration and pushes it
// back out of the brick rectangle. `bricks` is the set of bricks the ball
// overlaps in the SAME pass (a grid seam overlaps two bricks at once: the gap
// is 8 px, the ball 14 px across). The bounce is applied exactly ONCE against
// the shallowest axis — a `vy = -vy` repeated per brick would cancel out and
// the ball would plow through the seam.
//
//   per face : the axis with the smaller penetration is the face hit — flip it,
//              leave the other component exactly as it was;
//   corner   : equal penetrations mean a diagonal hit — flip both;
//   push out : reposition the ball outside the rectangle, otherwise the next
//              frame still overlaps and re-flips forever (sticky bounce).
function bounceOffBricks(ball, bricks) {
  // The winning brick is the one with the shallowest penetration overall.
  let win = null;
  let winDX = Infinity;
  let winDY = Infinity;
  for (const brick of bricks) {
    const dx = Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
    );
    const dy = Math.min(
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    );
    if (Math.min(dx, dy) < Math.min(winDX, winDY)) {
      win = brick;
      winDX = dx;
      winDY = dy;
    }
  }
  if (!win) return; // nothing overlaps (defensive)

  const left = ball.x + ball.r - win.x < win.x + win.w - (ball.x - ball.r);
  const top = ball.y + ball.r - win.y < win.y + win.h - (ball.y - ball.r);

  if (winDX < winDY) {
    // Vertical face: bounce horizontally, keep vy untouched.
    ball.vx = left ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = left ? win.x - ball.r : win.x + win.w + ball.r;
  } else if (winDY < winDX) {
    // Horizontal face: bounce vertically, keep vx untouched.
    ball.vy = top ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = top ? win.y - ball.r : win.y + win.h + ball.r;
  } else {
    // Corner: equal penetration — diagonal hit, flip both, exit both ways.
    ball.vx = left ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.vy = top ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.x = left ? win.x - ball.r : win.x + win.w + ball.r;
    ball.y = top ? win.y - ball.r : win.y + win.h + ball.r;
  }
}

// Safety net after the main bounce: if the ball still overlaps a brick (a
// multi-brick wedge), reposition it outside WITHOUT touching the velocity — the
// bounce has already been applied exactly once for this pass.
function pushOutRemaining(ball, bricks) {
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    const dxL = ball.x + ball.r - brick.x;
    const dxR = brick.x + brick.w - (ball.x - ball.r);
    const dyT = ball.y + ball.r - brick.y;
    const dyB = brick.y + brick.h - (ball.y - ball.r);
    if (Math.min(dxL, dxR) < Math.min(dyT, dyB)) {
      ball.x = dxL < dxR ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else {
      ball.y = dyT < dyB ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
  }
}

// Breaks every brick the ball hit in this pass (score + combo), then applies
// the bounce exactly once against the group. Shared by `step()` (swept hits
// during the move) and `frame()` (static overlaps).
function resolveBrickHits(state, hitBricks) {
  for (const brick of hitBricks) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
  bounceOffBricks(state.ball, hitBricks);
  pushOutRemaining(state.ball, state.bricks);
}

// Detects every brick the ball crossed during the move (prevX, prevY) -> ball,
// keeps the earliest contact, and resolves it: brick destroyed, score awarded,
// ball bounced off the right face and pushed out of the rectangle.
function resolveBricksSwept(state, prevX, prevY) {
  const ball = state.ball;
  const hits = [];
  let tMin = Infinity;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const t = sweepHit(ball, prevX, prevY, brick);
    if (t !== null) {
      hits.push({ brick, t });
      if (t < tMin) tMin = t;
    }
  }
  if (hits.length === 0) return;

  // The ball only ever reaches the earliest contact: every brick hit at that
  // same moment (e.g. both halves of a seam) is destroyed, the ones crossed
  // later on the phantom remainder of the move are not.
  const group = hits.filter((h) => h.t <= tMin + 1e-9).map((h) => h.brick);
  ball.x = prevX + (ball.x - prevX) * tMin;
  ball.y = prevY + (ball.y - prevY) * tMin;
  resolveBrickHits(state, group);
}

