// Main render loop. Brick collisions are normally resolved by `step()` before
// this runs (swept detection); this pass still resolves any brick the ball
// still overlaps (defensive, and the entry point the tests use), then draws
// only the bricks that survived.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: static overlap -> bounce once + push out + destroy, then draw.
  const overlapping = state.bricks.filter((b) => b.alive && collides(state.ball, b));
  if (overlapping.length > 0) {
    resolveBrickHits(state, overlapping);
  }

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

