+    const dy = Math.min(
+      ball.y + ball.r - brick.y,
+      brick.y + brick.h - (ball.y - ball.r),
+    );
+    if (Math.min(dx, dy) < Math.min(winDX, winDY)) {
+      win = brick;
+      winDX = dx;
+      winDY = dy;
+    }
