import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.newText:
// --- Issue #1: brick bounce -------------------------------------------------

// A canvas context that swallows everything (frame() only draws).
function fakeCtx() {
  const noop = () => {};
  return new Proxy(
    {},
    {
      get: (_, prop) => (prop === 'canvas' ? { width: WIDTH, height: HEIGHT } : noop),
      set: () => true,
    },
  );
}

// A single-brick field, ball already overlapping the brick's left face.
function stateWithBrick(overrides = {}) {
  const state = createState(1);
  state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
  Object.assign(state.ball, {
    x: 96,
    y: 110,
    r: BALL_R,
    vx: 300,
    vy: 30,
    ...overrides,
  });
  return state;
}

const DT = 1 / 60;

// frame() must bounce the ball off the face with the smallest penetration,
// leaving the other velocity component untouched.
test('brick: side hit flips vx only, ball pushed out of the rectangle', () => {
  const state = stateWithBrick(); // overlapping the left face
  frame(fakeCtx(), state);
  assert.ok(state.ball.vx < 0, 'vx should flip to the left');
  assert.ok(state.ball.vy > 0, 'vy must stay untouched');
  assert.ok(
    state.ball.x + BALL_R <= 100,
    `ball must be pushed left of the brick: x=${state.ball.x}`,
  );
  assert.equal(state.bricks[0].alive, false);
});

test('brick: top hit flips vy only', () => {
  const state = stateWithBrick({ x: 136, y: 96, vx: 30, vy: 300 });
  frame(fakeCtx(), state);
  assert.ok(state.ball.vy < 0, 'vy should flip upward');
  assert.ok(state.ball.vx > 0, 'vx must stay untouched');
  assert.ok(
    state.ball.y + BALL_R <= 100,
    `ball must be pushed above the brick: y=${state.ball.y}`,
  );
});

test('brick: corner hit flips both components', () => {
  const state = stateWithBrick({ x: 96, y: 96, vx: 300, vy: 300 });
  frame(fakeCtx(), state);
  assert.ok(state.ball.vx < 0, 'vx should flip');
  assert.ok(state.ball.vy < 0, 'vy should flip');
  assert.ok(state.ball.x + BALL_R <= 100 && state.ball.y + BALL_R <= 100);
});

test('brick seam: two neighbours hit in one pass bounce exactly once', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
    { x: 100 + BRICK_W + BRICK_GAP, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
  ];
  // Centred on the horizontal seam, 1 px below both bricks' bottom face.
  state.ball = { x: 176, y: 126, r: BALL_R, vx: 6, vy: -60 };
  frame(fakeCtx(), state);
  assert.ok(state.ball.vy > 0, 'vy must flip exactly once (a double flip cancels out)');
  assert.ok(state.ball.vx > 0, 'vx must stay untouched');
  assert.equal(state.bricks.filter((b) => !b.alive).length, 2, 'both bricks are destroyed');
});

test('brick tunnelling: fast ball cannot jump over a brick (swept detection in step)', () => {
  const state = createState(6);
  const brick = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
  state.bricks = [brick];
  // Below the brick before the move, fully above it after (35.5 px jump).
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05);
  assert.equal(brick.alive, false, 'the brick must be hit during the jump');
  assert.ok(state.ball.vy > 0, 'the ball must bounce back down');
});

test('brick: ball exiting through the bottom is still lost after a brick bounce', () => {
  const state = createState(1);
  state.bricks = []; // empty field: only the loss-line check remains
  state.ball = { x: 320, y: HEIGHT + 30, r: BALL_R, vx: 0, vy: 400 };
  const lost = step(state, DT);
  assert.equal(lost, true);
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

