+// Continuous (swept) collision: the move from (px, py) to the ball's current
+// position is a segment; we test it against the brick grown by the ball radius
+// (the expanded AABB). Returns the entry time t in [0, 1] along that segment,
+// or null if the segment never touches the brick. t = 0 means the ball already
+// overlapped the brick at the start of the move.
+//
+// This is what defeats tunnelling: at `ballSpeed(6)` (710 px/s) a stuttered
+// frame (50 ms cap) moves the ball 35.5 px, more than the 34 px needed to
+// clear a brick (BRICK_H + diameter) — a discrete before/after test would
+// never see the overlap, the sweep does.
+function sweepHit(ball, px, py, brick) {
+  const ex = brick.x - ball.r;
+  const ey = brick.y - ball.r;
+  const ew = brick.w + 2 * ball.r;
+  const eh = brick.h + 2 * ball.r;
+  const dx = ball.x - px;
+  const dy = ball.y - py;
+
+  let tEntry = 0;
+  let tExit = 1;
+
+  // Slab test on x.
+  if (Math.abs(dx) < 1e-12) {
+    if (px <= ex || px >= ex + ew) return null;
+  } else {
+    let t1 = (ex - px) / dx;
+    let t2 = (ex + ew - px) / dx;
+    if (t1 > t2) [t1, t2] = [t2, t1];
+    tEntry = Math.max(tEntry, t1);
+    tExit = Math.min(tExit, t2);
+  }
+  // Slab test on y.
+  if (Math.abs(dy) < 1e-12) {
+    if (py <= ey || py >= ey + eh) return null;
+  } else {
+    let t1 = (ey - py) / dy;
+    let t2 = (ey + eh - py) / dy;
+    if (t1 > t2) [t1, t2] = [t2, t1];
+    tEntry = Math.max(tEntry, t1);
+    tExit = Math.min(tExit, t2);
+  }
+
+  if (tEntry <= tExit && tEntry <= 1 && tExit >= 0) return Math.max(0, tEntry);
+  return null;
+}
